ROWS = [
dict(id="T111", d="STAT", t="The optimal constant in the Berry–Esseen inequality",
 s="Determine the least constant C_0 such that for every n and every iid sequence with E X = 0, E X² = 1 and E|X|³ = ρ < ∞, sup_x |P((X_1 + … + X_n)/√n ≤ x) − Φ(x)| ≤ C_0 ρ/√n. Esseen conjectured C_0 = (√10 + 3)/(6√(2π)) ≈ 0.4097, the value approached by a two-point distribution.",
 c="Esseen (1956) showed that no smaller constant works even as n → ∞ (Esseen, Skand. Aktuarietidskr. 1956, 160–170); the conjecture is that his value suffices for every n.",
 src="C.-G. Esseen, A moment inequality with an application to the central limit theorem, Skand. Aktuarietidskr. 39 (1956)",
 why="The Berry–Esseen bound is the basic quantitative form of the central limit theorem and is used throughout statistics; the sharp constant has been pursued for over eighty years, and each improvement has needed new analytic ideas.",
 st="Upper bounds went from 7.59 (Esseen 1942) through 0.7975 (van Beek 1972) to 0.4748 (Shevtsova 2011; Dokl. Math. 89 (2014) 378–381). For two-point summands Esseen's constant suffices for every n (J. Schulz, Universität Trier dissertation, 2016; see Zolotukhin, Nagaev and Chebotarev, arXiv:1810.09681). He and Cheng (arXiv:2609.06358v3) prove that Esseen's constant suffices for every n ≥ 2⌈exp(10^17)⌉, uniformly in the law. The constant for all n is open.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T112", d="COMB", t="The 1/3–2/3 conjecture for linear extensions",
 s="Every finite partially ordered set that is not a chain has two incomparable elements x and y such that a uniformly random linear extension places x before y with probability between 1/3 and 2/3.",
 c="The bounds are attained by the three-element poset with a single relation. The conjecture is usually credited to Kislitsyn (1968) and, independently, to Fredman (Theoret. Comput. Sci. 1 (1976)) and Linial (SIAM J. Comput. 13 (1984)).",
 src="S. S. Kislitsyn, Finite partially ordered sets and their associated sets of permutations, Mat. Zametki 4 (1968); M. L. Fredman, How good is the information theory bound in sorting?, Theoret. Comput. Sci. 1 (1976); N. Linial, The information-theoretic bound is good for merging, SIAM J. Comput. 13 (1984)",
 why="It is the best-known open problem about the uniform measure on linear extensions and has direct consequences for sorting with partial information.",
 st="Kahn and Saks (1984) found a pair with probability in [3/11, 8/11]; Brightwell, Felsner and Trotter (1995) improved this to [(5 − √5)/10, (5 + √5)/10] ≈ [0.276, 0.724], which is optimal for some infinite posets, and Aires, Chan, Pak and Panova (arXiv:2609.30888) improve that bound by a small ε > 0, the first general improvement since 1995. The conjecture holds for posets of width two (Linial 1984), semiorders (Brightwell 1989) and posets of height two (Trotter–Gehrlein–Fishburn, Order 9 (1992)). Open in general.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T113", d="COMB", t="The Gaussian product inequality",
 s="For every centred Gaussian vector (X_1, …, X_m) and all positive integers k_1, …, k_m, E ∏ X_i^{2k_i} ≥ ∏ E X_i^{2k_i}.",
 c="The case k_1 = … = k_m = 1 is equivalent to the real polarization problem for products of linear forms (Frenkel, Math. Res. Lett. 15 (2008); Malicet–Nourdin–Peccati–Poly, J. Funct. Anal. 270 (2016)).",
 src="W. V. Li and A. Wei, A Gaussian inequality for expected absolute products, J. Theoret. Probab. 25 (2012) 92–99",
 why="It is the moment form of a family of Gaussian correlation inequalities, tied to the real polarization constant and to permanents of positive semidefinite matrices. It is easy to state and has resisted the methods that proved the Gaussian correlation inequality.",
 st="Proved (claimed) for all positive exponents by Ouimet–Greaves (arXiv:2609.20234). Before that: m = 2, m = 3 with k_i = 1 (Frenkel 2008), three variables with even exponents (Herry–Malicet–Poly, arXiv:2211.07314), some three-dimensional cases with larger exponents (Russell–Sun, J. Math. Anal. Appl. 515 (2022)), and nonnegative covariances (by the Wick formula every pairing term is then nonnegative).",
 x="SOLVED (claimed): Ouimet and Greaves, A proof of the strong Gaussian product inequality conjecture (arXiv:2609.20234, 2026, unrefereed), prove E ∏|X_i|^{α_i} ≥ ∏ E|X_i|^{α_i} for every centred Gaussian vector, degenerate ones included, and all positive exponents α_i, with equality exactly for independent coordinates when the variances are positive; the even-integer form in this row is the case α_i = 2k_i. Through Frenkel's hafnian formulation it also gives the real linear polarization constant. Herry, Malicet and Poly (arXiv:2211.07314) had already settled three variables with even exponents. Read from the paper 14 Oct by the w673 audit."),
dict(id="T114", d="COMB", t="The B-conjecture for Gaussian measure",
 s="For the standard Gaussian measure γ on R^n and every origin-symmetric convex body K, the function t ↦ γ(e^t K) is log-concave on R.",
 c="Posed by Banaszczyk and popularized by Latała (Cordero-Erausquin–Fradelizi–Maurey 2004, p. 410).",
 src="R. Latała, On some inequalities for Gaussian measures, Proc. ICM 2002, vol. II, arXiv:math/0304343; D. Cordero-Erausquin, M. Fradelizi and B. Maurey, The (B) conjecture for the Gaussian measure of dilates of symmetric convex sets and related problems, J. Funct. Anal. 214 (2004)",
 why="It is a central open problem on Gaussian measure and convex bodies, in the same family as the Gaussian correlation inequality (proved by Royen in 2014) and the log-Brunn–Minkowski conjecture.",
 st="Proved for every symmetric convex set in every dimension, in the stronger diagonal form (Cordero-Erausquin–Fradelizi–Maurey 2004, Theorem 1). Related to the log-Brunn–Minkowski conjecture of Böröczky–Lutwak–Yang–Zhang (Adv. Math. 231 (2012)).",
 x="SOLVED in 2004: Cordero-Erausquin, Fradelizi and Maurey (J. Funct. Anal. 214 (2004) 410–427, doi:10.1016/j.jfa.2003.12.001) prove that t ↦ γ(e^t K) is log-concave for every symmetric convex set K in every dimension; their Theorem 1 is the stronger statement that (t_1, …, t_n) ↦ γ(e^{D(t_1, …, t_n)} K) is log-concave for diagonal D. The row's 'open for n ≥ 3' was wrong. The B-property for other symmetric log-concave measures is a different question. Read from the paper (pp. 410–411) 14 Oct by the w673 audit."),
dict(id="T115", x="SOLVED (claimed, unrefereed), 14 Nov 2026: the OpenAI math release preprint 'Average sensitivity of polynomial threshold functions' (25 Sep 2026, Thm 1) claims total influence at most 8 d sqrt(n) for every degree-d PTF, uniformly in d and n; the release has a Lean statement and solution for the bound. AI-written and unrefereed; this records the claim, not a check of the proof. Replacement row to be screened.", d="COMB", t="The Gotsman–Linial bound on the sensitivity of polynomial threshold functions",
 s="Every degree-d polynomial threshold function f = sign(p) on {−1, 1}^n has total influence (average sensitivity) at most C d √n, for an absolute constant C.",
 c="Gotsman and Linial conjectured the exact maximizer: the symmetric function that changes sign on the d middle layers. That exact form is false (Chapman, arXiv:2108.02288, 2021); this row is the weaker asymptotic form, the O(d√n) bound.",
 src="C. Gotsman and N. Linial, Spectral properties of threshold functions, Combinatorica 14 (1994)",
 why="Sensitivity bounds for threshold functions control learning, noise sensitivity and pseudorandom generators for polynomial threshold functions. The Gaussian analogue is known, so the problem is about passing from Gaussian space to the cube.",
 st="True for d = 1. Kane proved √n (log n)^{O(d log d)} 2^{O(d² log d)} (CCC 2013); earlier bounds of the form n^{1 − 1/O(2^d)} are due to Diakonikolas, Harsha, Klivans, Meka, Raghavendra, Servedio and Tan (STOC 2010, the merged version of two papers). The Gaussian surface area of degree-d threshold functions is O(d) (Kane 2011). arXiv:2604.08095 bounds E√s_f, the mean square root of the sensitivity, not the total influence. Open.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T116", d="STAT", t="Worst-case trace reconstruction",
 s="An unknown binary string x of length n is observed through independent traces, each obtained by deleting every bit independently with probability q ∈ (0, 1). Determine the order of the number of traces needed to reconstruct every x with high probability; in particular decide whether polynomially many traces suffice.",
 c="For a uniformly random x far fewer traces are needed, exp(O(log^{1/3} n)) (Holden–Pemantle–Peres–Zhai 2020); for the worst case the gap is now between polynomial and quasipolynomial bounds.",
 src="T. Batu, S. Kannan, S. Khanna and A. McGregor, Reconstructing strings from random traces, Proc. SODA 2004; F. Nazarov and Y. Peres, Trace reconstruction with exp(O(n^{1/3})) samples, Proc. STOC 2017",
 why="Trace reconstruction is the cleanest model of recovering a sequence from noisy copies (sequence alignment, DNA storage), and its gap between upper and lower bounds is among the widest in probability.",
 st="exp(O(n^{1/3})) traces suffice (De–O'Donnell–Servedio 2017; Nazarov–Peres 2017), improved to exp(Õ(n^{1/5})) (Chase 2021) and then to quasipolynomially many, for every retention probability at least 1/polylog n (Burudgunte–Valiant–Wang, arXiv:2607.04073). The best lower bound is Ω̃(n^{3/2}) (Chase, Ann. Inst. Henri Poincaré Probab. Stat. 57 (2021)), after n^{5/4} (Holden–Lyons, Ann. Appl. Probab. 30 (2020)). Whether polynomially many traces suffice is open.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T117", d="STAT", t="The capacity of the binary deletion channel",
 s="Determine the Shannon capacity C(d) of the binary deletion channel, in which each transmitted bit is deleted independently with probability d ∈ (0, 1) and the receiver sees the remaining bits in order.",
 c="No closed form is conjectured; the problem is to find one, or a characterization that determines C(d).",
 src="R. L. Dobrushin, Shannon's theorems for channels with synchronization errors, Problems Inform. Transmission 3 (1967); M. Mitzenmacher, A survey of results for deletion channels and related synchronization channels, Probab. Surv. 6 (2009)",
 why="It is the simplest channel with synchronization errors and the basic binary channel whose capacity is unknown; it is the information-theoretic side of trace reconstruction (T116).",
 st="The capacity exists as a limit of normalized mutual informations (Dobrushin 1967). C(d) ≥ (1 − d)/9 for every d (Mitzenmacher–Drinea, IEEE Trans. Inform. Theory 52 (2006)), with constructive lower bounds improved in arXiv:2609.24908; the expansion for small d is known to second order (Kanoria–Montanari, IEEE Trans. Inform. Theory 59 (2013); Kalai–Mitzenmacher–Sudan, ISIT 2010); upper bounds of the form c(1 − d) with c < 1 hold for large d (Rahmati–Duman, IEEE Trans. Inform. Theory 61 (2015)), and C(d) ≤ (1 − d)/4 for every d ≥ 13/20 (arXiv:2609.13351, with a Lean-checked certificate). arXiv:2609.19412 computes C(d) to within 0.0095 bits for every d and states that the exact capacity is unknown. Open.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T118", d="STAT", t="Computational hardness in the stochastic block model with five or more communities",
 s="For the symmetric stochastic block model with q ≥ 5 balanced communities and edge probabilities a/n and b/n, there is a nonempty region below the Kesten–Stigum bound (a − b)² = q(a + (q − 1)b) where weak recovery is information-theoretically possible but no polynomial-time algorithm achieves it.",
 c="A full proof would separate complexity classes; realistic targets are lower bounds for restricted algorithm classes (low-degree polynomials, message passing, local algorithms) and the exact location of the information-theoretic threshold.",
 src="A. Decelle, F. Krzakala, C. Moore and L. Zdeborová, Asymptotic analysis of the stochastic block model for modular networks and its algorithmic applications, Phys. Rev. E 84 (2011); E. Abbe, Community detection and stochastic block models: recent developments, J. Mach. Learn. Res. 18 (2018)",
 why="It is the leading example, with planted clique (T072), of a statistical–computational gap predicted by the cavity method; reconstruction on trees at the Kesten–Stigum bound (T067) is its local counterpart.",
 st="Above the Kesten–Stigum bound weak recovery is achieved in polynomial time (Massoulié 2014; Mossel–Neeman–Sly for q = 2; Abbe–Sandon, Comm. Pure Appl. Math. 71 (2018), for general q). For q ≥ 5 recovery below the bound is information-theoretically possible in part of the region (Banks–Moore–Neeman–Netrapalli, COLT 2016; Abbe–Sandon 2018). For detection with q fixed, low-degree polynomials fail below the bound (Hopkins–Steurer, FOCS 2017); arXiv:2610.08872 adds lower bounds for low-degree rules, cycle statistics and belief propagation, and arXiv:2503.03047 treats a growing number of communities. For q = 2 the two thresholds coincide (Mossel–Neeman–Sly); for q = 3 and 4 whether they coincide is open.",
 n="Status updated after the w673 audit (14 Oct).",
 loc="Abbe, arXiv:1703.10146, Section 10, Conjecture 2, p. 114"),
dict(id="T119", d="RG", t="The independence ratio of random cubic graphs",
 s="Determine the constant α_3 such that the independence number of a uniformly random 3-regular graph on n vertices, divided by n, converges in probability to α_3.",
 c="The limit exists (Bayati–Gamarnik–Tetali 2013). The one-step replica-symmetry-breaking prediction is α_3 ≈ 0.4509 (Barbier–Krzakala–Zdeborová–Zhang, J. Phys. Conf. Ser. 473 (2013), the value 0.45086).",
 src="N. C. Wormald, Models of random regular graphs, in Surveys in Combinatorics 1999 (Cambridge Univ. Press, 1999) 239–298; J. Ding, A. Sly and N. Sun, Maximum independent sets on random regular graphs, Acta Math. 217 (2016)",
 why="Independent sets in random regular graphs are the test case for the cavity method at small degree. Ding, Sly and Sun proved the one-step formula for large degree; small degrees are where the method has not been confirmed.",
 st="Bounds: α_3 ≥ 0.44533 (Csóka, arXiv:1602.02747, a local algorithm on large-girth graphs) and α_3 ≤ 0.45537 (McKay, Ars Combin. 23A (1987)). The one-step formula is proved for all d ≥ d_0 with d_0 large (Ding–Sly–Sun, arXiv:1310.4787), which does not reach d = 3. d = 3 is open.",
 n="Status updated after the w673 audit (14 Oct). Fame borderline in that audit; kept for now."),
dict(id="T120", d="RG", t="Finding large independent sets in sparse random graphs",
 s="In G(n, d/n) with d large, the independence number is (2 + o_d(1))(log d/d)n, while simple greedy algorithms find independent sets of size (1 + o_d(1))(log d/d)n. Prove that no polynomial-time algorithm finds an independent set of size (1 + ε)(log d/d)n with high probability, for fixed ε > 0 and all large d, or find one.",
 c="As for planted clique (T072), the full statement is a hardness conjecture; lower bounds are proved for restricted classes of algorithms.",
 src="D. Gamarnik and M. Sudan, Limits of local algorithms over sparse random graphs, Ann. Probab. 45 (2017); A. M. Frieze, On the independence number of random graphs, Discrete Math. 81 (1990)",
 why="It is the sparse analogue of Karp's question on cliques in G(n, 1/2) (T068) and the main test of the overlap gap property as an explanation of algorithmic hardness in random structures.",
 st="Local algorithms (factors of iid) cannot exceed (1 + 1/√2 + o(1))(log d/d)n (Gamarnik–Sudan 2017), and in fact (1 + o(1))(log d/d)n (Rahman–Virág 2017). The same limit holds for low-degree polynomial algorithms (Wein, arXiv:2010.06563; stronger low-degree hardness by Huang–Sellke, arXiv:2501.06427v2) and for stable algorithms through the overlap gap property (Gamarnik–Jagannath–Wein, FOCS 2020). Unrestricted polynomial-time algorithms are open.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id='T121',
 x='Moved on 12 Nov 2026 to the list of open problems in mathematics generally (06_math_research/top200_general_2026_11_10, seed_from_probability.tsv): Smooth dynamics (positive entropy of the standard map), not a probability problem.',
 d='DYN',
 t='Positive metric entropy of the Chirikov standard map',
 s='For the standard map f_K(x, y) = (x + y + K sin x, y + K sin x) on the 2-torus, prove that for some K, or for a set of K of positive measure, f_K has positive metric entropy with respect to Lebesgue measure, that is, a positive Lyapunov exponent on a set of positive area.',
 c='Often cited as a problem of Sinai (Topics in Ergodic Theory, 1994). For large K the entropy is expected to be about log(K/2). The difficulty is coexistence with elliptic islands, which exist for a residual set of large K (Duarte 1994); the stochastic sea has full Hausdorff dimension for topologically generic large K (Gorodetski, arXiv:1007.1474).',
 src='B. V. Chirikov, A universal instability of many-dimensional oscillator systems, Phys. Rep. 52 (1979) 263–379; Ya. G. Sinai, Topics in Ergodic Theory (Princeton Univ. Press, 1994)',
 why='The standard map is the basic model of area-preserving chaos (kicked rotors, particle accelerators); positive entropy for it would be the first proof of observable chaos for a natural conservative system without uniform hyperbolicity.',
 st='Elliptic islands exist for a residual set of large K (Duarte 1994), so the map is not uniformly hyperbolic. Positive Lyapunov exponents are proved for random perturbations (Blumenthal–Xue–Young, Ann. Math. 185, 2017) and for modified standard maps (Berger–Carrasco 2014). Positive topological entropy for every K ≠ 0 is proved (arXiv:2404.02209), and arXiv:2003.00236 studies the measure of maximal entropy, which may be singular; neither gives positive entropy for Lebesgue measure. Positive metric entropy is not known for any K.',
 n='Status updated after the w673 audit (14 Oct).'),
dict(id="T122", d="RG", t="The maximum cut of sparse random graphs",
 s="For fixed d > 1, determine the limit of MaxCut(G)/n for G = G(n, d/n), or for a uniformly random d-regular graph, and prove that it equals the zero-temperature value predicted by the cavity method for the diluted antiferromagnet.",
 c="For d ≤ 1, MaxCut/n → d/2 in G(n, d/n), since almost every edge lies in a tree component. As d → ∞ the answer is n(d/4 + P_*√(d/4) + o(√d)) with P_* ≈ 0.7632 the Parisi constant. For fixed d the prediction is the full replica-symmetry-breaking (Mézard–Parisi) cavity functional on a sparse graph, for which no rigorous variational formula is known.",
 src="M. Mézard and G. Parisi, The Bethe lattice spin glass revisited, Eur. Phys. J. B 20 (2001); A. Dembo, A. Montanari and S. Sen, Extremal cuts of sparse random graphs, Ann. Probab. 45 (2017)",
 why="MaxCut of a sparse random graph is the zero-temperature limit of the Viana–Bray diluted spin glass; a fixed-degree formula would carry the Parisi theory, proved in the dense mean-field case, over to sparse graphs, where most random optimization problems live.",
 st="The limit exists (Bayati–Gamarnik–Tetali 2013). The large-d asymptotics are due to Dembo–Montanari–Sen (arXiv:1503.03923). For diluted spin glasses the Parisi-type formula gives upper bounds (Franz–Leone, J. Stat. Phys. 111 (2003); Panchenko–Talagrand, Probab. Theory Related Fields 130 (2004)); Harangi (arXiv:2506.21296) proves 2-RSB upper bounds that beat 1-RSB, and Aronow and Lopatto (arXiv:2609.19057) show that max-cut and max-bisection have the same limit at every fixed degree of a random regular graph. The exact value for fixed d > 1 is open.",
 n="Statement revised after the w673 audit (14 Oct)."),
]
